<?php include 'db.php'; require_role('Patient'); $id=intval($_GET['id']); $msg=''; $test=$conn->query("SELECT RT.Price FROM APPOINTMENT A JOIN RADIOLOGY_TEST RT ON A.Test_ID=RT.Test_ID WHERE A.Appointment_ID=$id")->fetch_assoc(); $amount=$test?$test['Price']:0; if($_SERVER['REQUEST_METHOD']=='POST'){ $method=$_POST['method']; $stmt=$conn->prepare("INSERT INTO PAYMENT(Amount,Payment_Date,Payment_Method,Payment_Status,Appointment_ID) VALUES(?,CURDATE(),?,'Paid',?) ON DUPLICATE KEY UPDATE Payment_Status='Paid', Payment_Method=VALUES(Payment_Method), Payment_Date=CURDATE()"); $stmt->bind_param('dsi',$amount,$method,$id); $stmt->execute(); $msg='Payment saved successfully'; } $page_title='Payment'; include 'header.php'; ?>
<h2>Payment</h2><?php if($msg) echo '<div class="alert">'.esc($msg).'</div>'; ?><form class="form" method="post"><p>Amount: <b><?=esc($amount)?></b></p><select name="method"><option>Cash</option><option>Visa</option><option>Online</option></select><button>Pay</button></form><?php include 'footer.php'; ?>